<?php
declare(strict_types=1);

/**
 * Encryption at rest for DNS provider credentials and the SMTP password,
 * using libsodium secretbox (bundled with PHP 7.2+). The key is generated by
 * `php bin/manage.php init` into data/secret.key (mode 0600). Back that file
 * up with the database — without it, stored credentials can't be decrypted.
 */

function secret_key(): string
{
    static $key = null;
    if ($key !== null) {
        return $key;
    }
    $path = app_config('data_dir') . '/secret.key';
    if (!is_file($path)) {
        throw new RuntimeException('data/secret.key is missing. Run: php bin/manage.php init');
    }
    $key = sodium_hex2bin(trim((string)file_get_contents($path)));
    if (strlen($key) !== SODIUM_CRYPTO_SECRETBOX_KEYBYTES) {
        throw new RuntimeException('data/secret.key is corrupt.');
    }
    return $key;
}

function encrypt_str(string $plain): string
{
    $nonce = random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);
    return base64_encode($nonce . sodium_crypto_secretbox($plain, $nonce, secret_key()));
}

function decrypt_str(string $enc): string
{
    if ($enc === '') {
        return '';
    }
    $raw = base64_decode($enc, true);
    if ($raw === false || strlen($raw) <= SODIUM_CRYPTO_SECRETBOX_NONCEBYTES) {
        throw new RuntimeException('Encrypted value is malformed.');
    }
    $nonce = substr($raw, 0, SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);
    $plain = sodium_crypto_secretbox_open(substr($raw, SODIUM_CRYPTO_SECRETBOX_NONCEBYTES), $nonce, secret_key());
    if ($plain === false) {
        throw new RuntimeException('Could not decrypt a stored secret (wrong data/secret.key?).');
    }
    return $plain;
}

function encrypt_json(array $data): string
{
    return encrypt_str(json_encode($data, JSON_UNESCAPED_SLASHES));
}

function decrypt_json(string $enc): array
{
    $d = json_decode(decrypt_str($enc), true);
    return is_array($d) ? $d : [];
}

/** Agent and feed tokens are stored as SHA-256 hashes; tokens are 256-bit random, so no salt/KDF needed. */
function token_hash(string $token): string
{
    return hash('sha256', $token);
}
